"""Static graphics and self-contained offline interactive HTML."""
from pathlib import Path
import csv, json
import matplotlib.pyplot as plt
p=Path(__file__).parent/'results'
with (p/'departure_sweep.csv').open(encoding='utf-8') as f:
    rows=list(csv.DictReader(f))
data={m:[r for r in rows if int(r['transfer_margin_min'])==m] for m in [1,2,4]}
fig,ax=plt.subplots(figsize=(10,4.6))
q=data[1];x=[int(r['departure_min']) for r in q]
ax.plot(x,[int(r['near_arrival']) for r in q],label='Near transfer: 3 km',linewidth=2)
ax.plot(x,[int(r['far_arrival']) for r in q],label='Far transfer: 8 km',linewidth=2)
ax.plot(x,[int(r['arrival_min']) for r in q],label='Earliest arrival',linestyle='--',linewidth=1.4)
ax.set_xlabel('Journey request time (min)');ax.set_ylabel('Destination arrival (min)')
ax.set_title('Timetable dependence: nearest transfer is often not fastest')
ax.grid(True,alpha=.2);ax.legend();fig.tight_layout();fig.savefig(p/'departure_time_vs_arrival.png',dpi=150);plt.close(fig)
fig,ax=plt.subplots(figsize=(9,3.7))
zone=[('Pedestrian occupies B',0,3,1),('Car occupies A',0,3,2),('Car moves to B',3,5,3),('Follower occupies A',3,4,4)]
for title,start,end,i in zone:
    ax.barh(i,end-start,left=start,height=.52)
    ax.text(start+.04,i,title,va='center',ha='left',fontsize=9,color='white')
ax.set_yticks([]);ax.set_xlabel('Discrete-event time (ticks)')
ax.set_title('Sequential zone occupancy: downstream blockage extends upstream occupation')
ax.set_xlim(0,5.3);fig.tight_layout();fig.savefig(p/'sequential_zone_timeline.png',dpi=150);plt.close(fig)

payload=json.dumps(rows,ensure_ascii=False)
html='''<!doctype html><html lang="ko"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>T2 D23 · 시간 의존 경로 실험</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0c1424;color:#eef3ff;font:15px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1050px;margin:auto;padding:28px}.eyebrow{color:#8cc8fc;font-size:12px;letter-spacing:.12em;text-transform:uppercase}h1{font-size:clamp(24px,4vw,38px);line-height:1.2;margin:7px 0 12px}.sub{color:#b4c2d6}.layout{display:grid;grid-template-columns:1fr 1fr;gap:16px}.box{border:1px solid #364760;border-radius:16px;background:#172235;padding:20px}.controls{display:grid;gap:11px}input{width:100%;accent-color:#51b3e5}select{border:1px solid #536d87;border-radius:8px;background:#152339;color:white;padding:8px;font:inherit}.value{font-size:30px;font-weight:760}.far{color:#6edccb}.near{color:#f1bf78}.muted{color:#acb8ca;font-size:13px}.route{font-size:19px;font-weight:700;margin-top:6px}.chart{width:100%;height:auto;overflow:visible}svg text{font-family:system-ui}.bottom{margin-top:16px}table{width:100%;border-collapse:collapse}th,td{padding:9px 4px;text-align:left;border-bottom:1px solid #30425d}strong{color:white}.note{margin-top:18px;background:#273149;border-radius:12px;padding:12px;color:#d2deec}a{color:#7de3f2}@media(max-width:720px){.layout{grid-template-columns:1fr}.wrap{padding:14px}}</style></head>
<body><div class="wrap"><div class="eyebrow">R&E 2027 / T2 P11-Y D23 / Synthetic schedule</div><h1>가까운 환승이 항상 빠르지는 않다</h1><p class="sub">출발시각과 환승 여유시간을 바꿔 보세요. 이 화면은 가상 시간표를 사용한 정적 계산 결과이며 실제 교통편이 아닙니다.</p>
<div class="layout"><section class="box controls"><label for="start">출발 요청 <strong id="startLabel">0분</strong></label><input type="range" min="0" max="60" step="1" value="0" id="start"><label for="margin">최소 환승 여유시간</label><select id="margin"><option value="1">1분</option><option value="2">2분</option><option value="4">4분</option></select><div class="muted">O → N → D: 총 3 km · 연결편 간격 30분<br>O → F → D: 총 8 km · 연결편 간격 6분</div><svg viewBox="0 0 470 210" class="chart" aria-label="가상 정류장 노선도"><path d="M48 100 Q150 0 235 42 T425 100" stroke="#edb669" stroke-width="6" fill="none"/><path d="M48 100 Q142 205 235 164 T425 100" stroke="#67cfc0" stroke-width="6" fill="none"/><g fill="#eef3ff" stroke="#142136" stroke-width="4"><circle cx="48" cy="100" r="17"/><circle cx="235" cy="42" r="17"/><circle cx="235" cy="164" r="17"/><circle cx="425" cy="100" r="17"/></g><g fill="#142136" text-anchor="middle" font-size="15" font-weight="bold"><text x="48" y="105">O</text><text x="235" y="47">N</text><text x="235" y="169">F</text><text x="425" y="105">D</text></g><g fill="#c9d7e4" text-anchor="middle" font-size="14"><text x="137" y="31">2 km</text><text x="344" y="31">1 km</text><text x="135" y="185">4 km</text><text x="343" y="185">4 km</text></g></svg></section>
<section class="box"><div class="muted">현재 시간표에서 최조 도착 경로</div><div id="choice" class="route far"></div><div id="arrive" class="value"></div><div id="distance" class="sub"></div><hr style="border:0;border-top:1px solid #3b4f67;margin:19px 0"><table><thead><tr><th>환승</th><th>목적지 도착</th><th>이동거리</th></tr></thead><tbody><tr><td class="near">가까운 N</td><td id="nearArrival"></td><td>3 km</td></tr><tr><td class="far">먼 F</td><td id="farArrival"></td><td>8 km</td></tr></tbody></table><div id="diff" class="note"></div></section></div>
<section class="box bottom"><h2>출발시각에 따라 달라지는 도착시각</h2><svg id="graph" viewBox="0 0 800 235" class="chart" aria-label="가상 시간표 출발시각과 두 경로의 도착시각"></svg><p class="muted">선: 실제 시간표에서 계산한 도착시각. 도로 길이만 비교한 최단경로와 다릅니다. 환승 최소 여유시간을 변경하면 경로도 달라집니다.</p></section>
<section class="box bottom"><h2>시공간 점유와 대기열 역류의 연결</h2><p class="sub">별도의 합성 사건 실험에서 보행자가 B를 0~3틱 점유합니다. 차량은 A를 0~2틱 주행하지만, B가 3틱에 비워질 때까지 A를 점유합니다. 뒤차는 그제야 A에 진입할 수 있습니다.</p><svg viewBox="0 0 800 130" class="chart"><g fill="#c7d4e9" font-size="15"><text x="15" y="33">보행자 B</text><text x="15" y="64">차량 A</text><text x="15" y="95">차량 B</text><text x="15" y="124">뒤차 A</text></g><g><rect x="132" y="17" width="360" height="18" rx="5" fill="#f4b565"/><rect x="132" y="48" width="360" height="18" rx="5" fill="#568ec8"/><rect x="492" y="79" width="240" height="18" rx="5" fill="#6bd2b9"/><rect x="492" y="108" width="120" height="18" rx="5" fill="#9f9dee"/></g><g fill="#b8c8dd" font-size="13" text-anchor="middle"><text x="132" y="10">0</text><text x="372" y="10">2</text><text x="492" y="10">3</text><text x="732" y="10">5틱</text></g></svg><p class="muted">교통신호 제어는 수행하지 않았으며, 상류 링크의 실제 길이·차량 길이·보행 속도도 보정하지 않은 기계적 예시입니다.</p></section>
<div class="note">연구 경계: H3는 공간 집계를 위한 별도 도구이고 이 실험에는 H3 인덱스를 실제 사용하지 않았습니다. 버스 운행시간표는 합성 고정값이며 P12 신호정책 최적화는 동결 상태입니다.</div></div>
<script>const data=__DATA__;const start=document.getElementById('start'),margin=document.getElementById('margin');function draw(){let t=+start.value,m=+margin.value,items=data.filter(x=>+x.transfer_margin_min===m),r=items[t];document.getElementById('startLabel').textContent=t+'분';let choice=r.winner==='F'?'먼 환승 F 경로':'가까운 환승 N 경로';document.getElementById('choice').textContent=choice;document.getElementById('choice').className='route '+(r.winner==='F'?'far':'near');document.getElementById('arrive').textContent=r.arrival_min+'분 도착';document.getElementById('distance').textContent='탑승 이동거리 '+r.distance_km+' km · 출발 후 '+(r.arrival_min-t)+'분';document.getElementById('nearArrival').textContent=r.near_arrival+'분';document.getElementById('farArrival').textContent=r.far_arrival+'분';let delta=r.near_arrival-r.far_arrival;document.getElementById('diff').textContent=delta>0?'먼 환승이 '+delta+'분 먼저 도착합니다.':delta===0?'두 경로의 도착시각이 같습니다.':'가까운 환승이 '+(-delta)+'분 먼저 도착합니다.';const svg=document.getElementById('graph');let ymin=0,ymax=120,sx=x=>50+x/60*700,sy=y=>209-(y-ymin)/(ymax-ymin)*182;const mk=(field,color)=>'<polyline points="'+items.map(q=>sx(+q.departure_min)+','+sy(+q[field])).join(' ')+'" stroke="'+color+'" stroke-width="3" fill="none"/>';let pieces=['<path d="M50 14 V209 H760" stroke="#9ab4cc" stroke-width="1.2" fill="none"/>'];for(let j=0;j<=4;j++){let y=j*30;pieces.push('<text x="37" y="'+(sy(y)+5)+'" text-anchor="end" fill="#9ab4cc" font-size="13">'+y+'</text>')}for(let j=0;j<=6;j++){let x=j*10;pieces.push('<text x="'+sx(x)+'" y="229" text-anchor="middle" fill="#9ab4cc" font-size="13">'+x+'</text>')}pieces.push(mk('near_arrival','#f4bd77'),mk('far_arrival','#75ddc9'),'<line x1="'+sx(t)+'" y1="14" x2="'+sx(t)+'" y2="209" stroke="#ffffff" stroke-dasharray="4 4"/>');svg.innerHTML=pieces.join('')}start.addEventListener('input',draw);margin.addEventListener('change',draw);draw()</script></body></html>'''.replace('__DATA__',payload)
(p/'timetable_and_phases.html').write_text(html,encoding='utf-8')
print('visualizations',[(x.name,x.stat().st_size) for x in p.glob('*.png')],len(html))
